4	import { Settings } from '../config/Settings';
5	import { Audience } from '../audience/Audience';
6	import { Ledger } from '../audience/Ledger';
7	import { Delivery } from './Delivery';
8	import type { Post } from '../content/Posts';
9	import type { Subscriber } from '../audience/Audience';
10	import type { SendRow } from '../audience/Ledger';
11	
12	// The drip: each due subscriber receives their oldest unsent post, at
13	// most one email per CADENCE_HOURS. `plan()` is the pure decision —
14	// the cron, the /drip endpoint, and the dashboard's drip preview all
15	// read the same plan, so what the preview shows IS what the cron does.
16	class $Drip {
17	  static plan(
18	    posts: Post[],
19	    recipients: Subscriber[],
20	    sendRows: SendRow[],
21	    cadenceSeconds: number,
22	    now: number,
23	  ): DripPlanEntry[] {
24	    const sentByEmail = new Map<string, Set<string>>();
25	    const lastSentByEmail = new Map<string, number>();
26	    for (const row of sendRows) {
27	      let sentSet = sentByEmail.get(row.email);
28	      if (!sentSet) {
29	        sentSet = new Set();
30	        sentByEmail.set(row.email, sentSet);
31	      }
32	      sentSet.add(row.slug);
33	      lastSentByEmail.set(
34	        row.email,
35	        Math.max(lastSentByEmail.get(row.email) ?? 0, row.sentAt),
36	      );
37	    }
38	    return recipients.map((recipient) => {
39	      const sent = sentByEmail.get(recipient.email) ?? new Set();
40	      const nextPost = posts.find((candidate) => !sent.has(candidate.slug));
41	      const lastSentAt = lastSentByEmail.get(recipient.email) ?? 0;
42	      const dueAt = lastSentAt + cadenceSeconds;
43	      return {
44	        email: recipient.email,
45	        name: recipient.name,
46	        nextSlug: nextPost?.slug ?? null,
47	        sentCount: sent.size,
48	        lastSentAt: lastSentAt || null,
49	        dueAt: lastSentAt ? dueAt : now,
50	        sendNow: Boolean(nextPost) && now >= dueAt,
51	      };
52	    });
53	  }
54	
55	  // One full pass: plan, group due subscribers by the post they are
56	  // owed, one batched send per slug. Drips the DEFAULT list only —
57	  // other lists are broadcast/targeted-send audiences.
58	  static async run(env: Env): Promise<number> {
59	    const posts = await Posts.Class.load(env); // oldest first
60	    const recipients = await Audience.Class.active(
61	      env,
62	      Audience.Class.DEFAULT_LIST,
63	    );
64	    if (!posts.length || !recipients.length) return 0;
65	
66	    const sendRows = await Ledger.Class.allRows(env);
67	    const cadenceSeconds = (await Settings.Class.cadenceHours(env)) * 3600;
68	    const entries = this.plan(
69	      posts,
70	      recipients,
71	      sendRows,
72	      cadenceSeconds,
73	      Http.Class.nowSeconds(),
74	    );
75	
76	    const queueBySlug = new Map<string, Subscriber[]>();
77	    for (const entry of entries) {
78	      if (!entry.sendNow || !entry.nextSlug) continue;
79	      let queue = queueBySlug.get(entry.nextSlug);
80	      if (!queue) {
81	        queue = [];
82	        queueBySlug.set(entry.nextSlug, queue);
83	      }
84	      queue.push({ email: entry.email, name: entry.name });
85	    }
86	
87	    let delivered = 0;
88	    for (const [slug, group] of queueBySlug) {
89	      const post = Posts.Class.find(posts, slug);
90	      if (post)
91	        delivered += (await Delivery.Class.sendPost(env, post, group))
92	          .delivered;
93	    }
94	    return delivered;
95	  }
96	
97	  // The dashboard's preview: the same plan the next cron tick executes.
98	  static async preview(env: Env): Promise<DripPreview> {
99	    const posts = await Posts.Class.load(env);
100	    const recipients = await Audience.Class.active(
101	      env,
102	      Audience.Class.DEFAULT_LIST,
103	    );
104	    const sendRows = await Ledger.Class.allRows(env);
105	    const cadenceHours = await Settings.Class.cadenceHours(env);
106	    return {
107	      cadenceHours,
108	      entries: this.plan(
109	        posts,
110	        recipients,
111	        sendRows,
112	        cadenceHours * 3600,
113	        Http.Class.nowSeconds(),
114	      ),
115	    };
116	  }
117	}
118	
119	export namespace Drip {
120	  export const $Class = Static($Drip);
121	  export let Class = $Class;
122	}
123	
124	export interface DripPreview {
125	  cadenceHours: number;
126	  entries: DripPlanEntry[];
127	}
128	
129	export interface DripPlanEntry {
130	  email: string;
131	  name: string;
132	  nextSlug: string | null;
133	  sentCount: number;
134	  lastSentAt: number | null;
135	  dueAt: number;
136	  sendNow: boolean;
137	}
