6	import { Audience } from '../audience/Audience';
7	import type { Post } from '../content/Posts';
8	import type { Subscriber } from '../audience/Audience';
9	
10	// Postmark delivery — batch API on the broadcast message stream. Only an
11	// accepted message (ErrorCode 0) is written to the sends ledger, so a
12	// failed batch or a rejected recipient retries on the next pass instead
13	// of being falsely marked sent.
14	class $Delivery {
15	  static get POSTMARK_BATCH_URL() {
16	    return 'https://api.postmarkapp.com/email/batch';
17	  }
18	
19	  static get POSTMARK_EMAIL_URL() {
20	    return 'https://api.postmarkapp.com/email';
21	  }
22	
23	  // operator notifications are TRANSACTIONAL mail — Postmark's default
24	  // stream, never the broadcast newsletter stream
25	  static get NOTIFICATION_STREAM() {
26	    return 'outbound';
27	  }
28	
29	  // Postmark accepts up to 500 messages per batch call; batching keeps
30	  // subrequests far under the Workers free-plan cap (50/invocation).
31	  static get SEND_BATCH_SIZE() {
32	    return 500;
33	  }
34	
35	  // One line to the operator for every signup. Best-effort by design:
36	  // a notification failure is logged and never surfaces to the
37	  // subscriber — the signup itself already committed.
38	  static async notifySignup(
39	    env: Env,
40	    subscriber: Subscriber,
41	    list: string,
42	  ): Promise<void> {
43	    try {
44	      const audienceSize = await env.DB.prepare(
45	        'SELECT COUNT(DISTINCT email) AS total FROM subscribers ' +
46	          'WHERE email NOT IN (SELECT email FROM unsubscribes)',
47	      ).first<{ total: number }>();
48	      const response = await fetch(this.POSTMARK_EMAIL_URL, {
49	        method: 'POST',
50	        headers: {
51	          'X-Postmark-Server-Token': env.POSTMARK_SERVER_TOKEN,
52	          'content-type': 'application/json',
53	          accept: 'application/json',
54	        },
55	        body: JSON.stringify({
56	          From: `${env.SENDER_NAME} <${env.SENDER_EMAIL}>`,
57	          To: env.NOTIFY_EMAIL,
58	          Subject: `New subscriber: ${subscriber.email}`,
59	          MessageStream: this.NOTIFICATION_STREAM,
60	          TextBody:
61	            `${subscriber.email}${subscriber.name ? ` (${subscriber.name})` : ''} ` +
62	            `joined the "${list}" list.\n\n` +
63	            `Active audience: ${audienceSize?.total ?? '?'} subscribers.\n` +
64	            `Dashboard: ${env.WORKER_ORIGIN}/`,
65	        }),
66	      });
67	      if (!response.ok) {
68	        console.error(
69	          JSON.stringify({
70	            event: 'signup_notify_failed',
71	            status: response.status,
72	            body: (await response.text()).slice(0, 300),
73	          }),
74	        );
75	      }
76	    } catch (error) {
77	      console.error(
78	        JSON.stringify({ event: 'signup_notify_failed', error: String(error) }),
79	      );
80	    }
81	  }
82	
83	  // A whole-list broadcast of one post — the ledger-filtered core shared
84	  // by POST /broadcast and the scheduler.
85	  static async broadcastPost(
86	    env: Env,
