106	  static async sendPost(
107	    env: Env,
108	    post: Post,
109	    recipients: Subscriber[],
110	  ): Promise<DeliveryReport> {
111	    let delivered = 0;
112	    const outcomes: RecipientOutcome[] = [];
113	    for (
114	      let start = 0;
115	      start < recipients.length;
116	      start += this.SEND_BATCH_SIZE
117	    ) {
118	      const batch = recipients.slice(start, start + this.SEND_BATCH_SIZE);
119	      const messages = [];
120	      for (const recipient of batch) {
121	        const unsubscribe = await Security.Class.unsubscribeUrl(
122	          recipient.email,
123	          env,
124	        );
125	        messages.push({
126	          From: `${env.SENDER_NAME} <${env.SENDER_EMAIL}>`,
127	          ReplyTo: env.REPLY_TO,
128	          To: recipient.email,
129	          Subject: post.title,
130	          HtmlBody: post.emailHtml.replaceAll(
131	            '{{UNSUBSCRIBE_URL}}',
132	            unsubscribe,
133	          ),
134	          MessageStream: env.POSTMARK_STREAM,
135	          Headers: [
136	            { Name: 'List-Unsubscribe', Value: `<${unsubscribe}>` },
137	            {
138	              Name: 'List-Unsubscribe-Post',
139	              Value: 'List-Unsubscribe=One-Click',
140	            },
141	          ],
142	        });
143	      }
144	      const response = await fetch(this.POSTMARK_BATCH_URL, {
145	        method: 'POST',
146	        headers: {
147	          'X-Postmark-Server-Token': env.POSTMARK_SERVER_TOKEN,
148	          'content-type': 'application/json',
149	          accept: 'application/json',
150	        },
151	        body: JSON.stringify(messages),
152	      });
153	      if (!response.ok) {
154	        console.error(
155	          JSON.stringify({
156	            event: 'postmark_batch_failed',
157	            status: response.status,
158	            body: await response.text(),
159	          }),
160	        );
161	        for (const recipient of batch)
162	          outcomes.push({
163	            email: recipient.email,
164	            errorCode: response.status,
165	            message: 'Postmark batch call failed — will retry next run',
166	          });
167	        continue; // ledger stays unwritten — this batch retries next run
168	      }
169	      // per-message results: ErrorCode 0 = accepted; anything else (e.g.
170	      // 406 inactive recipient) is logged and NOT written to the ledger
171	      const results = (await response.json()) as PostmarkOutcome[];
172	      const timestamp = Http.Class.nowSeconds();
173	      const ledgerEntries = [];
174	      for (const [index, outcome] of results.entries()) {
175	        outcomes.push({
176	          email: batch[index].email,
177	          errorCode: outcome.ErrorCode,
178	          message: outcome.Message,
179	        });
180	        if (outcome.ErrorCode === 0) {
181	          ledgerEntries.push({
182	            email: batch[index].email,
183	            slug: post.slug,
184	            sentAt: timestamp,
185	          });
186	          delivered++;
187	        } else {
188	          console.error(
189	            JSON.stringify({
190	              event: 'postmark_message_rejected',
191	              recipient: batch[index].email,
192	              code: outcome.ErrorCode,
193	              message: outcome.Message,
194	            }),
195	          );
196	        }
197	      }
198	      await Ledger.Class.record(env, ledgerEntries);
199	    }
200	    return { delivered, outcomes };
201	  }
202	}
