42	        body.turnstileToken,
43	        request.headers.get('CF-Connecting-IP'),
44	        env,
45	      );
46	      if (!human)
47	        return Http.Class.json(
48	          { error: 'Verification failed — try again.' },
49	          403,
50	        );
51	    }
52	
53	    const name = String(body.name ?? '')
54	      .trim()
55	      .slice(0, 80);
