66	  static async unsubscribe(url: URL, env: Env): Promise<Response> {
67	    const address = (url.searchParams.get('email') ?? '').toLowerCase();
68	    const token = url.searchParams.get('token') ?? '';
69	    const expected = address
70	      ? await Security.Class.unsubscribeToken(address, env)
71	      : '';
72	    if (
73	      !address ||
74	      !(await Security.Class.timingSafeEqualStrings(token, expected))
75	    )
76	      return new Response('Invalid unsubscribe link.', { status: 400 });
77	
78	    await Audience.Class.suppress(env, address);
79	
80	    return Http.Class.html(
