89	  static async broadcast(request: Request, env: Env): Promise<Response> {
90	    if (!(await Security.Class.bearerAuthorized(request, env)))
91	      return Http.Class.json({ error: 'Unauthorized' }, 401);
92	
93	    const body = await Http.Class.readJsonBody<{ slug: string; list: string }>(
