116	  // The cron's exact pass, runnable on demand — same auth as /broadcast.
117	  static async drip(request: Request, env: Env): Promise<Response> {
118	    if (!(await Security.Class.bearerAuthorized(request, env)))
119	      return Http.Class.json({ error: 'Unauthorized' }, 401);
120	    const delivered = await Drip.Class.run(env);
