124	  // Postmark SubscriptionChange webhook: any suppression on their side
125	  // (their footer link, hard bounce, spam complaint) lands in OUR
126	  // unsubscribes table, and a reactivation clears it — D1 stays the
127	  // single source of truth. Configure in Postmark: newsletter stream →
128	  // Webhooks → Subscription change, with Basic auth postmark/ADMIN_SECRET.
129	  static async postmarkWebhook(request: Request, env: Env): Promise<Response> {
130	    if (!(await Security.Class.basicAuthorized(request, env)))
131	      return Http.Class.json({ error: 'Unauthorized' }, 401);
132	
133	    const event = await Http.Class.readJsonBody<{
134	      RecordType: string;
135	      Recipient: string;
136	      SuppressSending: boolean;
137	      SuppressionReason: string;
138	    }>(request);
139	    if (event.RecordType !== 'SubscriptionChange' || !event.Recipient)
140	      return Http.Class.json({ ok: true, ignored: true });
141	
142	    const address = event.Recipient.toLowerCase();
143	    if (event.SuppressSending) await Audience.Class.suppress(env, address);
144	    else await Audience.Class.unsuppress(env, address);
145	    console.error(
146	      JSON.stringify({
147	        event: 'postmark_suppression_sync',
148	        recipient: address,
149	        suppressed: Boolean(event.SuppressSending),
150	        reason: event.SuppressionReason ?? null,
151	      }),
152	    );
153	    return Http.Class.json({ ok: true });
154	  }
155	}
