320	  const frontmatterField = (source, field) => {
321	    const match = source.match(
322	      new RegExp(`^${field}:\\s*(?:'([^']*)'|"([^"]*)"|(.+))$`, 'm'),
323	    );
324	    return match ? (match[1] ?? match[2] ?? match[3] ?? '').trim() : '';
325	  };
326	  return readdirSync(blogDirectory)
327	    .filter((entry) => entry.endsWith('.md') && entry !== 'index.md')
328	    .map((entry) => {
329	      const slug = entry.slice(0, -'.md'.length);
330	      const source = readFileSync(resolve(blogDirectory, entry), 'utf8');
331	      const record = recordedDates[slug];
332	      return {
333	        slug,
334	        source,
335	        title: frontmatterField(source, 'title'),
336	        description: frontmatterField(source, 'description'),
337	        url: `${SITE}/blog/${slug}`,
338	        date: record?.date ?? null,
339	        timestamp: record?.timestamp ?? 0,
340	      };
341	    })
342	    .sort((first, second) => first.timestamp - second.timestamp);
343	}
