1	// Emits docs_v2/public/blog-index.json — the machine-readable post
2	// catalog the newsletter Worker reads: drip order, subjects, each
3	// post's COMPLETE email HTML (rendered by blog-email-renderer.mjs, the
4	// deterministic post → newsletter conversion), its committed embed
5	// screenshots (the X composer's attachable images), and a plain-text
6	// rendition of the body (the thread composer's raw material). The
7	// Worker substitutes only the per-recipient {{UNSUBSCRIBE_URL}}
8	// placeholder. Deterministic from committed files, so it runs in every
9	// build, including shallow-clone deploys, and ships with the site at
10	// https://ivue.dev/blog-index.json.
11	//   npm run sync:blog-index   (chained into build:docs)
12	import { readdirSync, writeFileSync } from 'node:fs';
13	import { resolve, dirname } from 'node:path';
14	import { fileURLToPath } from 'node:url';
15	import { loadPostsWithSource, renderEmail } from './blog-email-renderer.mjs';
16	
17	const SITE = 'https://ivue.dev';
18	const scriptDirectory = dirname(fileURLToPath(import.meta.url));
19	const outputPath = resolve(scriptDirectory, '../public/blog-index.json');
20	const embedsDirectory = resolve(scriptDirectory, '../public/blog/embeds');
21	const codeDirectory = resolve(scriptDirectory, '../public/blog/code');
22	
23	// committed screenshots, grouped by slug — numeric sort keeps -10
24	// after -9, matching document order
25	function shotsBySlug(directory, marker, urlPrefix) {
26	  const groups = new Map();
27	  const entries = readdirSync(directory)
28	    .map((entry) => entry.match(new RegExp(`^(.+)-${marker}-(\\d+)\\.png$`)))
29	    .filter(Boolean)
30	    .sort((first, second) =>
31	      first[1] === second[1]
32	        ? Number(first[2]) - Number(second[2])
33	        : first[1].localeCompare(second[1]),
34	    );
35	  for (const match of entries) {
36	    const urls = groups.get(match[1]) ?? [];
37	    urls.push(`${SITE}/${urlPrefix}/${match[0]}`);
38	    groups.set(match[1], urls);
39	  }
40	  return groups;
41	}
42	const embedsBySlug = shotsBySlug(embedsDirectory, 'embed', 'blog/embeds');
43	const codeBySlug = shotsBySlug(codeDirectory, 'code', 'blog/code');
44	
45	// The body as plain text: markdown noise stripped, code fences and
46	// embeds become short markers, links keep their words. Paragraphs stay
47	// separated by blank lines — the thread splitter breaks on them.
48	function plainText(source) {
49	  return source
50	    .replace(/^---[\s\S]*?---/, '') // frontmatter
51	    .replace(/<BlogPostDate \/>/g, '')
52	    .replace(/<!--[\s\S]*?-->/g, '')
53	    .replace(/^# .*$/m, '') // the H1 duplicates the title
54	    // a code-group renders ONE visible block (its active tab), and the
55	    // code shots follow visibility — the whole group is one marker;
56	    // standalone fences (all visible) stay one marker each
57	    .replace(/^::: ?code-group[\s\S]*?^:::$/gm, '[code — in the article]')
58	    .replace(/```[\s\S]*?```/g, '[code — in the article]')
59	    .replace(/^:::.*$/gm, '')
60	    .replace(/<ClientOnly>[\s\S]*?<\/ClientOnly>/g, '[live demo — in the article]')

